null กับ undefined:
let a;                // undefined (อัตโนมัติ — ไม่เคยถูกกำหนดค่า)
const b = null;       // null (ว่างเปล่าโดยเจตนา)

typeof null;          // 'object' — ⚠️ บั๊กของ JS
typeof undefined;     // 'undefined'

null == undefined;    // true — loose equality (หลีกเลี่ยง)
null === undefined;   // false — strict equality (ถูกต้อง)

// ?? ถือว่าเฉพาะ null/undefined เท่านั้นที่ 'ไม่มีค่า'
0 ?? 10;              // 0 (?? เก็บค่า 0)
0 || 10;              // 10 (|| ถือว่า 0 เป็น falsy)

