// Strict vs loose equality
console.log(5 === '5'); // false (ชนิดต่างกัน — ถูกต้อง)
console.log(5 == '5');  // true (coercion — หลีกเลี่ยง)

// NaN เป็นค่าเดียวที่ไม่เท่ากับตัวมันเอง
